/**
 * The country a number is probably from, read from the device only (docs/adr/20261111-phone-country-per-number): the
 * first language of the device whose region is a listed country, else the country of its time
 * zone, else null (Other). No request, no storage. `zoneCountries.json` is generated by
 * `scripts/phone/zone_countries.py`.
 */

import zoneCountries from './zoneCountries.json' with { type: 'json' }
import type { ListedCountry } from './types.ts'

const ZONES: ReadonlyMap<string, string> = new Map(Object.entries(zoneCountries.zones))

/** The upper-cased region of a language tag, or null when it has none or is not a tag. */
function regionOf(tag: string): string | null {
  try {
    return new Intl.Locale(tag).region?.toUpperCase() ?? null
  } catch {
    return null
  }
}

export function detectCountry(
  languages: readonly string[],
  timeZone: string,
  listed: readonly Pick<ListedCountry, 'code'>[],
): string | null {
  const codes = new Set(listed.map((country) => country.code))
  for (const tag of languages) {
    const region = regionOf(tag)
    if (region !== null && codes.has(region)) return region
  }
  const zone = ZONES.get(timeZone)
  return zone !== undefined && codes.has(zone) ? zone : null
}
